package com.collabspace.service;
import com.collabspace.dto.ChannelDtos.*; import com.collabspace.entity.*; import com.collabspace.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @RequiredArgsConstructor public class ChannelService {private final ChannelRepository channels;private final ChannelMemberRepository members;private final WorkspaceRepository workspaces;private final WorkspaceMemberRepository wm;private final CurrentUserService current; public List<ChannelResponse> list(UUID wid){requireWorkspaceMember(wid);return channels.findByWorkspaceIdOrderByNameAsc(wid).stream().filter(c->!c.isPrivateChannel()||members.existsByChannelIdAndUserId(c.getId(),current.get().getId())).map(this::dto).toList();} @Transactional public ChannelResponse create(UUID wid,CreateChannelRequest r){WorkspaceMember m=requireWorkspaceMember(wid);if(m.getRole()==WorkspaceRole.MEMBER)throw new SecurityException("Admin permission required");Workspace w=workspaces.findById(wid).orElseThrow();if(channels.findByWorkspaceIdAndNameIgnoreCase(wid,r.name()).isPresent())throw new IllegalArgumentException("Channel name already exists");Channel c=channels.save(Channel.builder().workspace(w).name(r.name().trim()).description(r.description()).privateChannel(r.privateChannel()).createdBy(current.get()).build());if(!c.isPrivateChannel()){wm.findByWorkspaceId(wid).forEach(x->add(c,x.getUser()));}else add(c,current.get());return dto(c);} @Transactional public ChannelResponse update(UUID id,UpdateChannelRequest r){Channel c=getMemberChannel(id);WorkspaceMember m=wm.findByWorkspaceIdAndUserId(c.getWorkspace().getId(),current.get().getId()).orElseThrow();if(m.getRole()==WorkspaceRole.MEMBER)throw new SecurityException("Admin permission required");c.setName(r.name().trim());c.setDescription(r.description());return dto(c);} @Transactional public void delete(UUID id){Channel c=getMemberChannel(id);WorkspaceMember m=wm.findByWorkspaceIdAndUserId(c.getWorkspace().getId(),current.get().getId()).orElseThrow();if(m.getRole()==WorkspaceRole.MEMBER)throw new SecurityException("Admin permission required");channels.delete(c);} @Transactional public void join(UUID id){Channel c=channels.findById(id).orElseThrow(()->new NoSuchElementException("Channel not found"));requireWorkspaceMember(c.getWorkspace().getId());if(c.isPrivateChannel())throw new SecurityException("Private channel requires an invitation");if(!members.existsByChannelIdAndUserId(id,current.get().getId()))add(c,current.get());} @Transactional public void leave(UUID id){Channel c=getMemberChannel(id);if(members.findByChannelId(id).size()<=1)throw new IllegalArgumentException("A channel must keep at least one member");members.deleteByChannelIdAndUserId(id,current.get().getId());} public Channel getMemberChannel(UUID id){Channel c=channels.findById(id).orElseThrow(()->new NoSuchElementException("Channel not found"));if(!members.existsByChannelIdAndUserId(id,current.get().getId()))throw new SecurityException("You are not a channel member");return c;} private WorkspaceMember requireWorkspaceMember(UUID id){return wm.findByWorkspaceIdAndUserId(id,current.get().getId()).orElseThrow(()->new SecurityException("You are not a workspace member"));} private void add(Channel c,User u){if(!members.existsByChannelIdAndUserId(c.getId(),u.getId()))members.save(ChannelMember.builder().channel(c).user(u).build());} private ChannelResponse dto(Channel c){return new ChannelResponse(c.getId(),c.getWorkspace().getId(),c.getName(),c.getDescription(),c.isPrivateChannel(),c.getCreatedBy().getId(),c.getCreatedAt());}}
